function sy3_home_content(): string {
    $contact = 'https://t.me/sy3_support_bot?start=site_sy3';
    $hero = sy3_p('СУТРИ / ЦИФРОВЫЕ РЕШЕНИЯ ДЛЯ БИЗНЕСА', 'eyebrow hero-kicker') .
