        sy3_g(
            sy3_p('<strong>Битрикс24</strong><br>Бизнес-партнёр') .
            sy3_p('<strong>Кейсы с примерами</strong><br>Что сделал и как проверил') .
            sy3_p('<strong>Разработка и аналитика</strong><br>Самостоятельно и с командой') .
            sy3_p('<strong>Личный контакт</strong><br>Лично веду проект'),
            'trust-strip'
        );
    $cases = sy3_p('01 / Работа в деталях', 'eyebrow') . sy3_g(sy3_h('<span id="selected-cases">Что уже сделано<br>для клиентов.</span>') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/cases/')) . '">Все кейсы</a>'), 'section-heading') . sy3_shortcode('[sy3_featured_cases]');
    $services = sy3_p('02 / Чем могу помочь', 'eyebrow') . sy3_g(sy3_h('Новый сайт.<br>Доработка. Автоматизация.') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/services/')) . '">Все направления</a>'), 'section-heading') .
        sy3_p('Сайт для клиентов, CRM для продаж, обмен с учётной системой или отчёт для руководителя. Выберите свою задачу — в каждом направлении есть примеры работ и описание первого шага.', 'section-intro') .
        sy3_shortcode('[sy3_core_services]') .
        sy3_p('Для задач по 1С и BI подключаю профильных специалистов. Я отвечаю за постановку задачи, координацию и проверку общего результата.', 'delivery-note');
    $process = sy3_p('03 / Как я работаю', 'eyebrow') . sy3_h('От вашего примера<br>до проверки результата.') . sy3_p('До разработки договариваемся, что должно измениться и как вы примете работу.', 'section-intro') . sy3_cols([
        sy3_p('01 / ЗАДАЧА', 'step-number') . sy3_h('Покажите, что мешает', 3) . sy3_p('Смотрю вместе с вами, как работает сайт, CRM или таблица. Уточняю задачу у тех, кто будет пользоваться решением.'),
        sy3_p('02 / ПЛАН', 'step-number') . sy3_h('Запишу, что сделаем', 3) . sy3_p('Готовлю требования, а при необходимости — ТЗ, схему или прототип. Согласуем состав первого этапа, стоимость и проверку.'),
        sy3_p('03 / РАЗРАБОТКА', 'step-number') . sy3_h('Сделаю или соберу команду', 3) . sy3_p('Сайты и интеграции могу разработать сам. Для задач по 1С и BI подключаю специалистов и веду общую работу.'),
        sy3_p('04 / ПРИЁМКА', 'step-number') . sy3_h('Покажу, как это работает', 3) . sy3_p('Проверяю согласованные действия, показываю результат и собираю замечания. Передаю инструкции для дальнейшей работы.')
    ], 'process-grid');
    $author = sy3_cols([
        sy3_image('artem-suyazov.jpg', 'Артём Суязов.', 'author-portrait') . sy3_p('Артём Суязов<br><span>IT-бизнес-партнёр · основатель Сутри</span>', 'author-name'),
