    $journal = sy3_p('05 / Практика и знания', 'eyebrow') . sy3_g(sy3_h('Что проверить<br>перед доработкой.') . sy3_p('<a class="text-link" href="' . esc_url(home_url('/journal/')) . '">Читать журнал</a>'), 'section-heading') . sy3_p('Как найти потерянную заявку, проверить интеграцию или выбрать первую задачу для ИИ. Разбираю на примерах.', 'section-intro') . sy3_shortcode('[sy3_cards type="post" count="3"]');
    $faq = sy3_home_faq_section();
    $cta = sy3_cols([
        sy3_p('Начнём с вашей задачи', 'eyebrow') . sy3_h('Есть задача?<br><em>Давайте разберёмся.</em>'),
